-- ARABEEZA revision 003
-- Replaces the small mixed practice set with 7 progressive levels (15 questions each).
-- Also persists each incorrect answer as one heart deduction.

begin;

create or replace function public.consume_heart()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_hearts integer;
begin
  if v_user is null then raise exception 'Silakan login terlebih dahulu.'; end if;
  select hearts into v_hearts from public.profiles where id = v_user for update;
  if v_hearts is null then raise exception 'Profil tidak ditemukan.'; end if;
  if v_hearts <= 0 then return jsonb_build_object('ok', false, 'hearts', 0, 'message', 'Nyawa habis.'); end if;
  update public.profiles set hearts = greatest(hearts - 1, 0) where id = v_user;
  return jsonb_build_object('ok', true, 'hearts', v_hearts - 1);
end;
$$;

grant execute on function public.consume_heart() to authenticated;

delete from public.questions
where lesson_id = (select id from public.lessons where slug = 'at-taaruf')
  and mode = 'mixed';

insert into public.questions (lesson_id, mode, skill, question_type, prompt, prompt_arabic, options, correct_answer, explanation, audio_text, sort_order, is_published)
select l.id, v.mode, v.skill, v.question_type, v.prompt, v.prompt_arabic, v.options, v.correct_answer, v.explanation, v.audio_text, v.sort_order, v.is_published
